import type { TechniqueCategory, TechniqueDefinition, TechniqueFamily, TechniqueResponseKind, TechniqueStepDefinition } from "./types";
import { specificCatalogWorkflow } from "./techniquesCatalogWorkflows";

export type CatalogCluster = {
  family: TechniqueFamily;
  cluster: string;
  category: TechniqueCategory;
  purpose: string;
  focusAreas?: string[];
  names: string;
};

const step = (id: string, title: string, prompt: string, responseKind: TechniqueResponseKind = "long-text"): TechniqueStepDefinition => ({ id, title, prompt, responseKind });
const slugify = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const summaryFor = (name: string, purpose: string, steps: TechniqueStepDefinition[]): string => {
  const workflowPath = steps.slice(0, 4).map((item) => item.title).join(" → ");
  return `${name} uses a ${workflowPath} workflow to ${purpose}.`;
};

function workflow(category: TechniqueCategory, cluster: string): TechniqueStepDefinition[] {
  if (category === "contrarian") return [
    step("target", "Target judgment", "State the judgment, plan, assumption, or interpretation being challenged."),
    step("challenge", "Structured challenge", `Apply the method using the ${cluster} lens. Record the strongest challenge rather than an easy counterexample.`),
    step("counterevidence", "Counterevidence", "List evidence, mechanisms, or cases that support the challenge.", "list"),
    step("tests", "Discriminating tests", "What observations would distinguish the challenged view from the alternative?", "list"),
    step("revision", "Revision", "What should change in the judgment, confidence, caveats, or monitoring plan?"),
  ];
  if (category === "imaginative") return [
    step("focus", "Focus", "Define the question, system, actor, or future space to explore."),
    step("drivers", "Inputs and drivers", `Identify the important drivers, constraints, uncertainties, or dimensions relevant to ${cluster}.`, "list"),
    step("generate", "Generate alternatives", "Use the method to create distinct possibilities without collapsing them too early.", "list"),
    step("compare", "Compare", "Which alternatives are most plausible, consequential, surprising, or informative, and why?"),
    step("signposts", "Signposts and implications", "What indicators, implications, or next analytic moves follow?", "list"),
  ];
  if (category === "diagnostic") return [
    step("question", "Question or claim", "State exactly what is being examined, explained, estimated, or tested."),
    step("inputs", "Evidence and inputs", `Gather the evidence, observations, variables, cases, or source material required for ${cluster}.`, "list"),
    step("analysis", "Apply the method", "Work through the method explicitly. Record intermediate comparisons, classifications, patterns, or calculations rather than only the conclusion."),
    step("alternatives", "Alternatives and limitations", "What rival explanations, missing data, measurement problems, boundary choices, or method limitations could change the result?", "list"),
    step("judgment", "Judgment and confidence", "State the result, confidence, key reasons, and the next information that would most improve the assessment."),
  ];
  return [
    step("objective", "Objective", "State the decision, problem, process, or product this method will support."),
    step("criteria", "Inputs and criteria", `List the inputs, criteria, stakeholders, constraints, or alternatives relevant to ${cluster}.`, "list"),
    step("apply", "Apply the method", "Work through the method consistently and preserve the reasoning behind scores, rankings, choices, or observations."),
    step("sensitivity", "Sensitivity and tradeoffs", "Which assumptions, criteria, uncertainties, or tradeoffs most affect the result?"),
    step("decision", "Result and next action", "Record the result, rationale, residual uncertainty, and next action."),
  ];
}

