export const CATALOG_BUILT_IN_TECHNIQUES: TechniqueDefinition[] = CATALOG_CLUSTERS.flatMap((group) =>
  group.names.split("|").map((name) => {
    const steps = specificCatalogWorkflow(name) ?? workflow(group.category, group.cluster);
    return {
      id: `builtin:catalog-${group.family}-${slugify(name)}`,
      name,
      summary: summaryFor(name, group.purpose, steps),
      category: group.category,
      family: group.family,
      cluster: group.cluster,
      builtIn: true,
      version: 1,
      steps,
      createdAt: null,
      updatedAt: null,
    };
  }),
);
